//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::arena::{Arena, NodeId};
use serde::Deserialize;
use serde_json::Value;
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Operation {
    kind: String,
    parent: usize,
    target: Option<usize>,
    child: usize,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Vec<Operation>>,
    results: Vec<Value>,
}
#[test]
fn pinned_goldmark_child_mutations() {
    let f: Fixture =
        serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/arena.json")).unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (index, (ops, expected)) in f.requests.into_iter().zip(f.results).enumerate() {
        let mut arena = Arena::default();
        for i in 0..8 {
            assert_eq!(arena.insert(i), NodeId(i));
        }
        for i in [2, 3, 4] {
            arena.append_child(NodeId(0), NodeId(i));
        }
        for i in [5, 6] {
            arena.append_child(NodeId(1), NodeId(i));
        }
        let mut snapshots = vec![serde_json::to_value(arena.nodes()).unwrap()];
        for op in ops {
            let parent = NodeId(op.parent);
            let child = NodeId(op.child);
            let target = op.target.map(NodeId);
            match op.kind.as_str() {
                "append" => arena.append_child(parent, child),
                "remove" => arena.remove_child(parent, child),
                "clear" => arena.remove_children(parent),
                "before" => arena.insert_before(parent, target, child),
                "after" => arena.insert_after(parent, target.unwrap(), child),
                "replace" => arena.replace_child(parent, target.unwrap(), child),
                _ => panic!("unknown operation"),
            }
            snapshots.push(serde_json::to_value(arena.nodes()).unwrap());
        }
        assert_eq!(
            serde_json::to_value(snapshots).unwrap(),
            expected,
            "case {index}"
        );
    }
}
